{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { Sheet } from './eval.js'
import { parseAddr, addrName, fmt } from './util.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(s)
  const raw = m[1]
  const a = parseAddr(raw)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${raw}`)
  const key = addrName(a)
  if (cells.has(key)) fail(`error: line ${i + 1}: cell ${key} is declared twice`)
  cells.set(key, { col: a.col, row: a.row, key, content: m[2] })
}

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const list = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)
let out = ''
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of list) out += `${c.key}=${fmt(sheet.get(c.key))}\n`
} else {
  for (const c of list) {
    let line = c.key + ':'
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      if (ast) {
        const refs = new Map()
        collect(ast, refs)
        const arr = [...refs.values()].sort((x, y) => x.col - y.col || x.row - y.row)
        for (const r of arr) line += ' ' + addrName(r)
      }
    }
    out += line + '\n'
  }
}
process.stdout.write(out)

function collect(n, refs) {
  switch (n.k) {
    case 'ref':
      if (n.a) refs.set(addrName(n.a), n.a)
      break
    case 'range':
      if (n.a && n.b) {
        const c0 = Math.min(n.a.col, n.b.col), c1 = Math.max(n.a.col, n.b.col)
        const r0 = Math.min(n.a.row, n.b.row), r1 = Math.max(n.a.row, n.b.row)
        for (let c = c0; c <= c1; c++) for (let r = r0; r <= r1; r++) refs.set(c + ',' + r, { col: c, row: r })
      }
      break
    case 'un': collect(n.x, refs); break
    case 'bin': collect(n.l, refs); collect(n.r, refs); break
    case 'call': for (const x of n.args) collect(x, refs); break
  }
}
"}

