{"file_path":"src/util.js","content":"export function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  let col = 0
  for (const ch of m[1].toUpperCase()) col = col * 26 + (ch.charCodeAt(0) - 64)
  return { col, row }
}

export function addrName({ col, row }) {
  let s = ''
  let c = col
  while (c > 0) {
    s = String.fromCharCode(65 + ((c - 1) % 26)) + s
    c = Math.floor((c - 1) / 26)
  }
  return s + row
}

export function fmt(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}
"}

{"file_path":"src/parse.js","content":"import { parseAddr } from './util.js'

function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<=|>=|<>|[-+*\/^=<>():,])/.exec(src.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

// Returns an AST, or null when the grammar rejects the formula.
export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const peekOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const FAIL = new Error('grammar')

  function comparison() {
    let l = additive()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (peekOp('+') || peekOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (peekOp('*') || peekOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (peekOp('^')) {
      p++
      return { k: 'bin', op: '^', l, r: power() }
    }
    return l
  }
  function unary() {
    if (peekOp('-') || peekOp('+')) {
      const op = toks[p++].v
      return { k: 'un', op, x: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw FAIL
    const t = toks[p++]
    if (t.t === 'num') return { k: 'num', v: t.v }
    if (t.t === 'op') {
      if (t.v === '(') {
        const e = comparison()
        if (!peekOp(')')) throw FAIL
        p++
        return e
      }
      throw FAIL
    }
    if (peekOp('(')) {
      p++
      const args = []
      if (peekOp(')')) p++
      else {
        for (;;) {
          args.push(comparison())
          if (peekOp(',')) { p++; continue }
          if (peekOp(')')) { p++; break }
          throw FAIL
        }
      }
      return { k: 'call', name: t.v.toUpperCase(), args }
    }
    const up = t.v.toUpperCase()
    if (peekOp(':')) {
      p++
      if (p >= toks.length || toks[p].t !== 'word') throw FAIL
      const w = toks[p++].v
      if (peekOp('(')) throw FAIL
      return { k: 'range', a: parseAddr(t.v.toUpperCase()), b: parseAddr(w.toUpperCase()) }
    }
    if (up === 'TRUE') return { k: 'bool', v: true }
    if (up === 'FALSE') return { k: 'bool', v: false }
    return { k: 'ref', a: parseAddr(up) }
  }

  try {
    const e = comparison()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e === FAIL) return null
    throw e
  }
}
"}

{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'
import { parseAddr, addrName } from './util.js'

const ERRS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const err = (v) => ({ t: 'e', v })
const num = (v) => ({ t: 'n', v })
const ZERO = num(0)

function finite(x) {
  return Number.isFinite(x) ? num(x) : err('#DIV/0!')
}

// number reading of a value; returns number or an error value
function asNum(v) {
  if (v.t === 'n') return v.v
  if (v.t === 'b') return v.v ? 1 : 0
  return err(v.t === 'e' ? v.v : '#VALUE!')
}

function cmpCodePoints(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d < 0 ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] < rank[b.t] ? -1 : 1
  if (a.t === 's') return cmpCodePoints(a.v, b.v)
  const x = Number(a.v), y = Number(b.v)
  return x < y ? -1 : x > y ? 1 : 0
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.visiting = new Set()
  }

  get(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    const cell = this.cells.get(key)
    if (!cell) return ZERO
    if (this.visiting.has(key)) return err('#CYCLE!')
    this.visiting.add(key)
    let v
    try {
      v = this.compute(cell.content)
    } finally {
      this.visiting.delete(key)
    }
    this.memo.set(key, v)
    return v
  }

  compute(c) {
    if (c[0] === '=') {
      const ast = parseFormula(c.slice(1))
      if (!ast) return err('#ERR!')
      return this.ev(ast)
    }
    if (c === '') return ZERO
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(Number(c))
    if (ERRS.has(c)) return err(c)
    return { t: 's', v: c }
  }

  ref(a) {
    if (!a) return err('#REF!')
    return this.get(addrName(a))
  }

  // expand a function argument to a list of values
  expand(n) {
    if (n.k !== 'range') return [this.ev(n)]
    if (!n.a || !n.b) return [err('#REF!')]
    const c0 = Math.min(n.a.col, n.b.col), c1 = Math.max(n.a.col, n.b.col)
    const r0 = Math.min(n.a.row, n.b.row), r1 = Math.max(n.a.row, n.b.row)
    const out = []
    for (let c = c0; c <= c1; c++) for (let r = r0; r <= r1; r++) out.push(this.get(addrName({ col: c, row: r })))
    return out
  }

  ev(n) {
    switch (n.k) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'ref': return this.ref(n.a)
      case 'range': return err('#ERR!')
      case 'un': {
        const x = this.ev(n.x)
        if (x.t === 'e') return x
        const v = asNum(x)
        if (typeof v !== 'number') return v
        return finite(n.op === '-' ? -v : v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
  }

  bin(n) {
    const l = this.ev(n.l)
    if (l.t === 'e') return l
    const r = this.ev(n.r)
    if (r.t === 'e') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const c = compare(l, r)
      const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
      return { t: 'b', v: res }
    }
    const a = asNum(l)
    if (typeof a !== 'number') return a
    const b = asNum(r)
    if (typeof b !== 'number') return b
    switch (n.op) {
      case '+': return finite(a + b)
      case '-': return finite(a - b)
      case '*': return finite(a * b)
      case '/': return b === 0 ? err('#DIV/0!') : finite(a / b)
      case '^': return finite(Math.pow(a, b))
    }
  }

  call(n) {
    const name = n.name
    const argc = n.args.length
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return err('#NAME?')
    if (name === 'IF') {
      if (argc !== 3) return err('#ERR!')
      if (n.args[0].k === 'range') return err('#ERR!')
      const c = this.ev(n.args[0])
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      const br = n.args[truth ? 1 : 2]
      if (br.k === 'range') return err('#ERR!')
      return this.ev(br)
    }
    if (name === 'ABS') {
      if (argc !== 1) return err('#ERR!')
    } else if (argc < 1) return err('#ERR!')

    const vals = []
    for (const a of n.args) for (const v of this.expand(a)) vals.push(v)
    const firstErr = vals.find((v) => v.t === 'e')
    if (firstErr) return firstErr
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
    if (name === 'ABS' && vals.length !== 1) return err('#ERR!')
    const nums = []
    for (const v of vals) {
      const x = asNum(v)
      if (typeof x !== 'number') return x
      nums.push(x)
    }
    switch (name) {
      case 'ABS': return finite(Math.abs(nums[0]))
      case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
      case 'AVG': {
        const s = nums.reduce((t, x) => t + x, 0)
        return finite(s / nums.length)
      }
      case 'MIN': return num(nums.reduce((m, x) => (x < m ? x : m), nums[0]))
      case 'MAX': return num(nums.reduce((m, x) => (x > m ? x : m), nums[0]))
    }
  }
}
"}

